:root {
  color-scheme: light dark;
  --bg: #f7f5f2;
  --panel: #ffffff;
  --text: #1f1b16;
  --muted: #6b6259;
  --border: #ddd4c7;
  --accent: #9a4b2f;
  --accent-bg: #f3e3da;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1a1714;
    --panel: #242019;
    --text: #eee7dc;
    --muted: #a89d8d;
    --border: #3a332a;
    --accent: #e08a5c;
    --accent-bg: #3a271d;
  }
}

* {
  box-sizing: border-box;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, sans-serif;
  margin: 0;
  padding: 2rem 1rem 4rem;
}

h1 {
  text-align: center;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  color: var(--muted);
  margin-top: 0;
  margin-bottom: 2rem;
}

.page {
  max-width: 960px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem 1.5rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
}

.field label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

.field input,
.field select {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

.submit-row {
  margin-top: 1rem;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.6rem 1.5rem;
  border-radius: 6px;
  font-size: 1rem;
  cursor: pointer;
}

button:hover {
  opacity: 0.9;
}

.error {
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 6px;
  padding: 0.75rem 1rem;
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  max-width: 480px;
  margin: 0 auto;
  border: 2px solid var(--border);
}

.chart-cell {
  border: 1px solid var(--border);
  padding: 0.4rem;
  font-size: 0.8rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 0;
}

.chart-cell.blank {
  background: var(--bg);
}

.chart-cell.ascendant {
  background: var(--accent-bg);
  border-color: var(--accent);
}

.cell-sign {
  font-weight: 600;
  font-size: 0.75rem;
  color: var(--muted);
}

.cell-planets {
  font-weight: 600;
  word-break: break-word;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

th, td {
  text-align: left;
  padding: 0.4rem 0.6rem;
  border-bottom: 1px solid var(--border);
}

th {
  color: var(--muted);
  font-weight: 600;
}

tr.current-period {
  background: var(--accent-bg);
}

.section-title {
  margin-top: 0;
}

