  flex-direction: column;
  gap: 1.25rem;
}

.tab-radio {
  display: none;
}

.tab-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.3rem;
  border-bottom: 2px solid var(--border);
  padding-bottom: 2px;
}

.tab-bar label {
  padding: 0.6rem 1.1rem;
  cursor: pointer;
  border-radius: var(--radius-sm) var(--radius-sm) 0 0;
  color: var(--muted);
  font-size: 0.88rem;
  font-weight: 600;
  user-select: none;
  border-bottom: 3px solid transparent;
  transition: background 0.15s ease, color 0.15s ease;
}

.tab-bar label:hover {
  color: var(--accent);
  background: var(--bg-alt);
}

.tab-panel {
  display: none;
  flex-direction: column;
  gap: 1.5rem;
}

#tab-chart:checked ~ .tab-bar label[for="tab-chart"],
#tab-dasha:checked ~ .tab-bar label[for="tab-dasha"],
#tab-aspects:checked ~ .tab-bar label[for="tab-aspects"],
#tab-jaimini:checked ~ .tab-bar label[for="tab-jaimini"],
#tab-divisional:checked ~ .tab-bar label[for="tab-divisional"],
#tab-ashtakavarga:checked ~ .tab-bar label[for="tab-ashtakavarga"],
#tab-panchanga:checked ~ .tab-bar label[for="tab-panchanga"],
#tab-compat:checked ~ .tab-bar label[for="tab-compat"],
#tab-tools:checked ~ .tab-bar label[for="tab-tools"],
#tab-ask:checked ~ .tab-bar label[for="tab-ask"] {
  background: var(--accent-bg);
  color: var(--accent);
  border-bottom-color: var(--accent-2);
}

#tab-chart:checked ~ #panel-chart,
#tab-dasha:checked ~ #panel-dasha,
#tab-aspects:checked ~ #panel-aspects,
#tab-jaimini:checked ~ #panel-jaimini,
#tab-divisional:checked ~ #panel-divisional,
#tab-ashtakavarga:checked ~ #panel-ashtakavarga,
#tab-panchanga:checked ~ #panel-panchanga,
#tab-compat:checked ~ #panel-compat,
#tab-tools:checked ~ #panel-tools,
#tab-ask:checked ~ #panel-ask {
  display: flex;
}

/* ---- Divisional Charts sub-tabs: flexbox order + adjacent-sibling, so
   adding another chart needs zero new CSS (unlike the per-ID lists above,
   which don't scale to 24 entries). ---- */

.subtab-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.85rem;
}

.subtab-radio {
  display: none;
}

.subtab-label {
  order: 0;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 600;
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--muted);
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.subtab-panel {
  order: 1;
  flex-basis: 100%;
  display: none;
  padding-top: 1.25rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--border);
}

.subtab-radio:checked + .subtab-label {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.subtab-radio:checked + .subtab-label + .subtab-panel {
  display: block;
}

/* ---- Chart tab: Rasi/Dasha/Navamsa on the left, Planets on the right ---- */

.chart-tab-grid {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) minmax(320px, 1.4fr);
  gap: 1.5rem;
  align-items: start;
}

.chart-tab-left,
.chart-tab-right {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .chart-tab-grid {
    grid-template-columns: 1fr;
  }
}

/* ---- Dasha drill-down (Pratyantardasha/Sookshma/Prana, dasha_detail.html) ---- */

.dasha-detail-level {
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  margin-bottom: 0.5rem;
  padding: 0.5rem 0.75rem;
}

.dasha-detail-level summary {
  cursor: pointer;
  font-size: 0.9rem;
  color: var(--accent);
  font-weight: 600;
}

.dasha-detail-level table {
  margin-top: 0.5rem;
}

.dasha-detail-level .dasha-detail-level {
  margin-top: 0.5rem;
  margin-bottom: 0;
}

.sub-periods-form {
  margin: 0;
  display: inline;
}

.sub-periods-button {
  padding: 0.3rem 0.7rem;
  font-size: 0.78rem;
  box-shadow: none;
}

/* ---- Ashtakavarga: 3x3 tile grid of mini South Indian score-charts ---- */

.ashtakavarga-tiles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.1rem;
}

@media (max-width: 700px) {
  .ashtakavarga-tiles {
    grid-template-columns: repeat(2, 1fr);
  }
}

.ashtakavarga-tile {
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.75rem;
  background: var(--bg-alt);
}

.mini-chart-title {
  margin: 0 0 0.6rem;
  font-size: 0.85rem;
  font-weight: 700;
  text-align: center;
  color: var(--text);
}

.mini-chart-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.mini-chart-cell {
  border: 1px solid var(--border);
  background: var(--panel);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  min-height: 0;
  color: var(--text);
}

.mini-chart-cell.blank {
  background: transparent;
  border-color: transparent;
}

.mini-chart-cell.natal-occupied {
  border-color: var(--accent-2);
  box-shadow: inset 0 0 0 1px var(--accent-2);
}

/* Bindu-count heatmap: 0-8 scale blended between the panel color and the
   primary accent, so higher scores read visually "hotter" at a glance -
   the "graph" feel, without any charting library or JS. */
.mini-chart-cell.bindus-0 { background: var(--panel); }
.mini-chart-cell.bindus-1 { background: color-mix(in srgb, var(--accent) 10%, var(--panel)); }
.mini-chart-cell.bindus-2 { background: color-mix(in srgb, var(--accent) 20%, var(--panel)); }
.mini-chart-cell.bindus-3 { background: color-mix(in srgb, var(--accent) 32%, var(--panel)); }
.mini-chart-cell.bindus-4 { background: color-mix(in srgb, var(--accent) 44%, var(--panel)); color: var(--text); }
.mini-chart-cell.bindus-5 { background: color-mix(in srgb, var(--accent) 56%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-6 { background: color-mix(in srgb, var(--accent) 68%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-7 { background: color-mix(in srgb, var(--accent) 82%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-8 { background: var(--accent); color: #fff; }

.mini-chart-cell.bindus-4 .cell-sign,
.mini-chart-cell.bindus-5 .cell-sign,
.mini-chart-cell.bindus-6 .cell-sign,
.mini-chart-cell.bindus-7 .cell-sign,
.mini-chart-cell.bindus-8 .cell-sign {
  color: inherit;
  opacity: 0.85;
}

.cell-bindus {
  font-weight: 700;
  font-size: 0.95rem;
}

.pending-note {
  margin: 0;
  text-align: center;
}

.sav-legend {
  margin-top: 1rem;
  max-width: 460px;
}

.sav-band-critically-weak { color: var(--danger); font-weight: 700; }
.sav-band-below-average { color: var(--warning); font-weight: 700; }
.sav-band-average { color: var(--muted); font-weight: 700; }
.sav-band-strong { color: var(--success); font-weight: 700; }
.sav-band-exceptional { color: var(--info); font-weight: 700; }

/* ---- Score meter: CSS-only horizontal bar, color-banded like the SAV
   legend above - reusable later for Shadbala/Vimshopaka/Bhava Bala. ---- */

.score-meter {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 160px;
}

.score-meter-track {
  flex: 1;
  height: 10px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.score-meter-fill {
  height: 100%;
  border-radius: 999px;
}

.score-meter-fill.sav-band-critically-weak { background: var(--danger); }
.score-meter-fill.sav-band-below-average { background: var(--warning); }
.score-meter-fill.sav-band-average { background: var(--muted); }
.score-meter-fill.sav-band-strong { background: var(--success); }
.score-meter-fill.sav-band-exceptional { background: var(--info); }

.score-meter-value {
  font-size: 0.82rem;
  font-weight: 700;
  min-width: 2ch;
  text-align: right;
}

