:root {
  color-scheme: light dark;

  --bg: #f4f3ee;
  --bg-alt: #eceae2;
  --panel: #ffffff;
  --text: #1c2130;
  --muted: #656d82;
  --border: #dfe1e8;
  --border-strong: #c7cbd8;

  /* Primary: deep indigo (the "official" tone). Secondary: warm gold. */
  --accent: #26315c;
  --accent-bg: #e7e9f5;
  --accent-2: #a9791a;
  --accent-2-bg: #f8eed2;

  --success: #1e7a3d;
  --success-bg: #e3f3e7;
  --warning: #b3691e;
  --warning-bg: #faeedb;
  --danger: #b3261e;
  --danger-bg: #fbe4e1;
  --info: #1e6f7a;
  --info-bg: #e1f0f2;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 2px rgba(20, 24, 40, 0.07);
  --shadow-md: 0 6px 20px rgba(20, 24, 40, 0.09);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #12141d;
    --bg-alt: #191c28;
    --panel: #1b1e2b;
    --text: #e7e9f2;
    --muted: #98a0b5;
    --border: #2b2f42;
    --border-strong: #3a3f57;

    --accent: #8fa0e6;
    --accent-bg: #232a48;
    --accent-2: #e3b34f;
    --accent-2-bg: #3a2f14;

    --success: #4fbf75;
    --success-bg: #16301f;
    --warning: #e0a24f;
    --warning-bg: #3a2a10;
    --danger: #ea6b62;
    --danger-bg: #3a1614;
    --info: #5cc2d0;
    --info-bg: #102e33;

    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.35);
    --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.45);
  }
}

* {
  box-sizing: border-box;
}

body {
  background:
    radial-gradient(1200px 400px at 50% -120px, var(--accent-bg) 0%, transparent 70%),
    var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, sans-serif;
  margin: 0;
  padding: 2.5rem 1rem 4rem;
}

h1 {
  text-align: center;
  margin-bottom: 0.25rem;
  letter-spacing: 0.01em;
  font-size: 2rem;
}

h1::before {
  content: "\2609  ";
  color: var(--accent-2);
}

.subtitle {
  text-align: center;
  color: var(--muted);
  margin-top: 0;
  margin-bottom: 2.5rem;
  font-size: 0.95rem;
}

.page {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.5rem 1.75rem;
  box-shadow: var(--shadow-sm);
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
}

.field label {
  display: block;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 0.35rem;
}

.field input,
.field select {
  width: 100%;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text);
  font-size: 0.95rem;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.field input:focus,
.field select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-bg);
}

.place-field {
  grid-column: span 2;
}

.time-inputs {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.time-inputs select {
  padding: 0.55rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg);
  color: var(--text);
}

.advanced {
  margin-top: 1rem;
  border-top: 1px solid var(--border);
  padding-top: 0.75rem;
}

.advanced summary {
  cursor: pointer;
  color: var(--accent);
  font-weight: 600;
  font-size: 0.9rem;
}

.advanced .form-grid {
  margin-top: 0.75rem;
}

.hint {
  color: var(--muted);
  font-size: 0.8rem;
  margin: 0.25rem 0 0;
  line-height: 1.5;
}

.candidate-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.candidate-form {
  margin: 0;
}

.candidate-button {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--border);
  box-shadow: none;
}

.candidate-button:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: none;
}

.submit-row {
  margin-top: 1rem;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.65rem 1.6rem;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: var(--shadow-sm);
  transition: transform 0.1s ease, box-shadow 0.15s ease, opacity 0.15s ease;
}

button:hover {
  opacity: 0.95;
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

button:active {
  transform: translateY(0);
}

.error {
  background: var(--danger-bg);
  color: var(--danger);
  border: 1px solid var(--danger);
  border-radius: var(--radius-sm);
  padding: 0.75rem 1rem;
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  max-width: 480px;
  margin: 0 auto;
  border: 2px solid var(--border-strong);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

.chart-cell {
  border: 1px solid var(--border);
  background: var(--panel);
  padding: 0.4rem;
  font-size: 0.8rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 0;
  transition: background 0.15s ease;
}

.chart-cell.blank {
  background: var(--bg-alt);
}

.chart-cell.ascendant {
  background: var(--accent-bg);
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.cell-sign {
  font-weight: 600;
  font-size: 0.75rem;
  color: var(--muted);
}

.cell-planets {
  font-weight: 700;
  word-break: break-word;
  color: var(--accent);
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

th, td {
  text-align: left;
  padding: 0.55rem 0.7rem;
  border-bottom: 1px solid var(--border);
}

th {
  color: var(--muted);
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  background: var(--bg-alt);
}

tbody tr:hover {
  background: var(--bg-alt);
}

tr.current-period {
  background: var(--accent-bg);
}

tr.current-period:hover {
  background: var(--accent-bg);
}

.section-title {
  margin-top: 0;
  padding-bottom: 0.6rem;
  border-bottom: 2px solid var(--accent-2-bg);
  font-size: 1.15rem;
}

.compat-row {
  margin-top: 1.25rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.compat-row label {
  cursor: pointer;
}

.person-b-section {
  margin-top: 1rem;
  padding: 1rem;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
}

