  margin-top: 0;
  font-size: 0.95rem;
  color: var(--muted);
}

.person-b-section {
  display: none;
}

.compat-row:has(.compat-checkbox:checked) + .person-b-section {
  display: block;
}

tr.dosha-row td,
td.dosha-row {
  color: var(--danger);
  font-weight: 600;
}

tr.total-row {
  border-top: 2px solid var(--border-strong);
  font-weight: 700;
}

.answer-box {
  margin-top: 1rem;
  padding: 1rem 1.25rem;
  background: var(--accent-bg);
  border-radius: var(--radius-md);
  border-left: 4px solid var(--accent);
}

.answer-question {
  color: var(--muted);
  margin-top: 0;
}

.answer-text {
  margin-bottom: 0;
  white-space: pre-wrap;
}

