:root {
  color-scheme: light dark;
  --bg: #f7f5f2;
  --panel: #ffffff;
  --text: #1f1b16;
  --muted: #6b6259;
  --border: #ddd4c7;
  --accent: #9a4b2f;
  --accent-bg: #f3e3da;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #1a1714;
    --panel: #242019;
    --text: #eee7dc;
    --muted: #a89d8d;
    --border: #3a332a;
    --accent: #e08a5c;
    --accent-bg: #3a271d;
  }
}

* {
  box-sizing: border-box;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", system-ui, sans-serif;
  margin: 0;
  padding: 2rem 1rem 4rem;
}

h1 {
  text-align: center;
  margin-bottom: 0.25rem;
}

.subtitle {
  text-align: center;
  color: var(--muted);
  margin-top: 0;
  margin-bottom: 2rem;
}

.page {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.25rem 1.5rem;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
}

.field label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

.field input,
.field select {
  width: 100%;
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

.place-field {
  grid-column: span 2;
}

.time-inputs {
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.time-inputs select {
  padding: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

.advanced {
  margin-top: 1rem;
  border-top: 1px solid var(--border);
  padding-top: 0.75rem;
}

.advanced summary {
  cursor: pointer;
  color: var(--muted);
  font-size: 0.9rem;
}

.advanced .form-grid {
  margin-top: 0.75rem;
}

.hint {
  color: var(--muted);
  font-size: 0.8rem;
  margin: 0.25rem 0 0;
}

.candidate-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.candidate-form {
  margin: 0;
}

.candidate-button {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--border);
}

.candidate-button:hover {
  border-color: var(--accent);
}

.submit-row {
  margin-top: 1rem;
}

button {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.6rem 1.5rem;
  border-radius: 6px;
  font-size: 1rem;
  cursor: pointer;
}

button:hover {
  opacity: 0.9;
}

.error {
  background: var(--accent-bg);
  color: var(--accent);
  border: 1px solid var(--accent);
  border-radius: 6px;
  padding: 0.75rem 1rem;
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 2px;
  aspect-ratio: 1 / 1;
  max-width: 480px;
  margin: 0 auto;
  border: 2px solid var(--border);
}

.chart-cell {
  border: 1px solid var(--border);
  padding: 0.4rem;
  font-size: 0.8rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 0;
}

.chart-cell.blank {
  background: var(--bg);
}

.chart-cell.ascendant {
  background: var(--accent-bg);
  border-color: var(--accent);
}

.cell-sign {
  font-weight: 600;
  font-size: 0.75rem;
  color: var(--muted);
}

.cell-planets {
  font-weight: 600;
  word-break: break-word;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9rem;
}

th, td {
  text-align: left;
  padding: 0.4rem 0.6rem;
  border-bottom: 1px solid var(--border);
}

th {
  color: var(--muted);
  font-weight: 600;
}

tr.current-period {
  background: var(--accent-bg);
}

.section-title {
  margin-top: 0;
}

.compat-row {
  margin-top: 1.25rem;
  padding-top: 1rem;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.compat-row label {
  cursor: pointer;
}

.person-b-section {
  margin-top: 1rem;
  padding: 1rem;
  border: 1px dashed var(--border);
  border-radius: 8px;
}

.person-b-section h3 {
  margin-top: 0;
  font-size: 0.95rem;
  color: var(--muted);
}

.person-b-section {
  display: none;
}

.compat-row:has(.compat-checkbox:checked) + .person-b-section {
  display: block;
}

tr.dosha-row td,
td.dosha-row {
  color: var(--accent);
}

tr.total-row {
  border-top: 2px solid var(--border);
}

.answer-box {
  margin-top: 1rem;
  padding: 1rem;
  background: var(--accent-bg);
  border-radius: 8px;
}

.answer-question {
  color: var(--muted);
  margin-top: 0;
}

.answer-text {
  margin-bottom: 0;
  white-space: pre-wrap;
}

/* ---- Tabs (pure CSS: radio inputs + labels, no JavaScript) ---- */

.tabs-wrapper {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.tab-radio {
  display: none;
}

.tab-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border-bottom: 2px solid var(--border);
}

.tab-bar label {
  padding: 0.6rem 1.1rem;
  cursor: pointer;
  border-radius: 8px 8px 0 0;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 600;
  user-select: none;
}

.tab-bar label:hover {
  color: var(--text);
}

.tab-panel {
  display: none;
  flex-direction: column;
  gap: 1.5rem;
}

#tab-chart:checked ~ .tab-bar label[for="tab-chart"],
#tab-dasha:checked ~ .tab-bar label[for="tab-dasha"],
#tab-aspects:checked ~ .tab-bar label[for="tab-aspects"],
#tab-jaimini:checked ~ .tab-bar label[for="tab-jaimini"],
#tab-divisional:checked ~ .tab-bar label[for="tab-divisional"],
#tab-ashtakavarga:checked ~ .tab-bar label[for="tab-ashtakavarga"],
#tab-panchanga:checked ~ .tab-bar label[for="tab-panchanga"],
#tab-compat:checked ~ .tab-bar label[for="tab-compat"],
#tab-tools:checked ~ .tab-bar label[for="tab-tools"],
#tab-ask:checked ~ .tab-bar label[for="tab-ask"] {
  background: var(--accent-bg);
  color: var(--accent);
}

#tab-chart:checked ~ #panel-chart,
#tab-dasha:checked ~ #panel-dasha,
#tab-aspects:checked ~ #panel-aspects,
#tab-jaimini:checked ~ #panel-jaimini,
#tab-divisional:checked ~ #panel-divisional,
#tab-ashtakavarga:checked ~ #panel-ashtakavarga,
#tab-panchanga:checked ~ #panel-panchanga,
#tab-compat:checked ~ #panel-compat,
#tab-tools:checked ~ #panel-tools,
#tab-ask:checked ~ #panel-ask {
  display: flex;
}

/* ---- Divisional Charts sub-tabs: flexbox order + adjacent-sibling, so
   adding another chart needs zero new CSS (unlike the per-ID lists above,
   which don't scale to 24 entries). ---- */

.subtab-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem;
}

.subtab-radio {
  display: none;
}

.subtab-label {
  order: 0;
  padding: 0.4rem 0.75rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.85rem;
  color: var(--muted);
}

.subtab-panel {
  order: 1;
  flex-basis: 100%;
  display: none;
  padding-top: 1rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--border);
}

.subtab-radio:checked + .subtab-label {
  background: var(--accent-bg);
  color: var(--accent);
}

.subtab-radio:checked + .subtab-label + .subtab-panel {
  display: block;
}

/* ---- Chart tab: Rasi/Dasha/Navamsa on the left, Planets on the right ---- */

.chart-tab-grid {
  display: grid;
  grid-template-columns: minmax(320px, 1fr) minmax(320px, 1.4fr);
  gap: 1.5rem;
  align-items: start;
}

.chart-tab-left,
.chart-tab-right {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

@media (max-width: 900px) {
  .chart-tab-grid {
    grid-template-columns: 1fr;
  }
}

/* ---- Dasha drill-down (Pratyantardasha/Sookshma/Prana, dasha_detail.html) ---- */

.dasha-detail-level {
  border: 1px solid var(--border);
  border-radius: 6px;
  margin-bottom: 0.5rem;
  padding: 0.5rem 0.75rem;
}

.dasha-detail-level summary {
  cursor: pointer;
  font-size: 0.9rem;
}

.dasha-detail-level table {
  margin-top: 0.5rem;
}

.dasha-detail-level .dasha-detail-level {
  margin-top: 0.5rem;
  margin-bottom: 0;
}

.sub-periods-form {
  margin: 0;
  display: inline;
}

.sub-periods-button {
  padding: 0.25rem 0.6rem;
  font-size: 0.8rem;
}

/* ---- Ashtakavarga: 3x3 tile grid of mini South Indian score-charts ---- */

.ashtakavarga-tiles {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}

@media (max-width: 700px) {
  .ashtakavarga-tiles {
    grid-template-columns: repeat(2, 1fr);
  }
}

.ashtakavarga-tile {
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.6rem;
}

.mini-chart-title {
  margin: 0 0 0.5rem;
  font-size: 0.85rem;
  text-align: center;
  color: var(--muted);
}

.mini-chart-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 1px;
  aspect-ratio: 1 / 1;
  border: 1px solid var(--border);
}

.mini-chart-cell {
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  min-height: 0;
}

.mini-chart-cell.blank {
  background: var(--bg);
}

.mini-chart-cell.natal-occupied {
  background: var(--accent-bg);
  border-color: var(--accent);
}

.cell-bindus {
  font-weight: 700;
  font-size: 0.95rem;
}

.pending-note {
  margin: 0;
  text-align: center;
}

.sav-legend {
  margin-top: 1rem;
  max-width: 420px;
}

.sav-band-critically-weak { color: #b3261e; font-weight: 600; }
.sav-band-below-average { color: #b3691e; font-weight: 600; }
.sav-band-average { color: var(--muted); font-weight: 600; }
.sav-band-strong { color: #1e7a3d; font-weight: 600; }
.sav-band-exceptional { color: #1e6f7a; font-weight: 700; }

