545	      <div class="tab-panel" id="panel-divisional">
546	        <div class="panel">
547	          <h2 class="section-title">&#128193; 23 Standard Varga (Divisional) Charts</h2>
548	          <p class="hint">
549	            Bhava Chalit (house-cusp based) plus all 23 classical divisional charts. Charts whose classical
550	            formula is well-established across sources are shown as a full chart; the rest are listed with
551	            a note explaining why they're held back rather than shown as a guess.
552	          </p>
553	          <div class="subtab-group">
554	            <div class="subtab-heading subtab-heading-available">&#9989; Available now - click to view</div>
555	            <div class="subtab-heading subtab-heading-held">&#128274; Not yet available (held pending a confirmed source)</div>
556	            {% for entry in divisional_chart_entries %}
557	            <input type="radio" name="divisional-subtabs" id="subtab-{{ entry.code }}" class="subtab-radio"
558	                   {% if loop.first %}checked{% endif %}>
559	            <label for="subtab-{{ entry.code }}" class="subtab-label {% if not entry.grid %}held{% endif %}">
560	              {% if not entry.grid %}&#128274; {% endif %}{{ entry.name }}
561	            </label>
562	            <div class="subtab-panel">
563	              {% if entry.grid %}
564	              <div class="chart-grid">
565	                {% for row in entry.grid %}
566	                  {% for cell in row %}
567	                    {% if cell is none %}
568	                    <div class="chart-cell blank"></div>
569	                    {% else %}
570	                    <div class="chart-cell {% if cell.is_ascendant %}ascendant{% endif %}">
571	                      <span class="cell-sign">{{ cell.sign.value }} (H{{ cell.house }})</span>
572	                      <span class="cell-planets">{{ cell.planet_labels | join(", ") }}</span>
573	                    </div>
574	                    {% endif %}
575	                  {% endfor %}
576	                {% endfor %}
577	              </div>
578	              {% else %}
579	              <div class="held-chart-notice">
580	                <p class="held-chart-title">&#128274; Not shown on purpose - this isn't a bug</p>
581	                <p class="hint pending-note">{{ entry.held_reason }}</p>
582	              </div>
583	              {% endif %}
584	            </div>
585	            {% endfor %}
586	          </div>

