file.content:
/* ---- Divisional Charts sub-tabs: flexbox order + adjacent-sibling, so
   adding another chart needs zero new CSS (unlike the per-ID lists above,
   which don't scale to 24 entries). ---- */

.subtab-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.85rem;
}

.subtab-radio {
  display: none;
}

.subtab-label {
  order: 0;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 600;
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--muted);
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.subtab-panel {
  order: 3;
  flex-basis: 100%;
  display: none;
  padding-top: 1.25rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--border);
}

.subtab-radio:checked + .subtab-label {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.subtab-radio:checked + .subtab-label + .subtab-panel {
  display: block;
}

/* Two visually separated groups within the same flex container/radio
   group: available (order 0) charts first, a divider heading, then held
   (order 2) charts - achieved purely with `order`, so no per-chart CSS is
   needed and the underlying label+panel adjacency (required for the
   :checked selector above) is untouched. */

.subtab-heading {
  order: -1;
  flex-basis: 100%;
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--muted);
  margin: 0.2rem 0 0.1rem;
}

.subtab-heading-held {
  order: 1;
  margin-top: 0.75rem;
  padding-top: 0.6rem;
  border-top: 1px dashed var(--border-strong);
}

.subtab-label.held {
  order: 2;
  border-style: dashed;
  color: var(--muted);
  font-style: italic;
}

.subtab-radio:checked + .subtab-label.held {
  background: var(--bg-alt);
  color: var(--muted);
  border-color: var(--border-strong);

