/* ---- Divisional Charts sub-tabs: two side-by-side columns (available /
   held), each its own independent flexbox order + adjacent-sibling group,
   so adding another chart needs zero new CSS (unlike the per-ID lists
   above, which don't scale to 24 entries). Both columns' radios share one
   `name`, so only one chart is ever selected across the whole tab. ---- */

.subtab-columns {
  display: flex;
  gap: 1.25rem;
  align-items: flex-start;
}

.subtab-column {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.subtab-heading {
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--muted);
}

.subtab-group {
  display: flex;
  flex-wrap: wrap;
  align-content: flex-start;
  gap: 0.35rem;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 0.85rem;
  min-height: 100%;
}

.subtab-radio {
  display: none;
}

.subtab-label {
  order: 0;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 600;
  background: var(--panel);
  border: 1px solid var(--border);
  color: var(--muted);
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.subtab-panel {
  order: 1;
  flex-basis: 100%;
  display: none;
  padding-top: 1.25rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--border);
}

.subtab-radio:checked + .subtab-label {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.subtab-radio:checked + .subtab-label + .subtab-panel {
  display: block;
}

.subtab-label.held {
  border-style: dashed;
  color: var(--muted);
  font-style: italic;
}

.subtab-radio:checked + .subtab-label.held {
  background: var(--bg-alt);
  color: var(--muted);
  border-color: var(--border-strong);
}

@media (max-width: 800px) {
  .subtab-columns {
    flex-direction: column;
  }
}

