/* Fixed, theme-independent semantic colors per the user's exact spec
   (red/orange/yellow/parrot-green/thick-green) - these carry a fixed
   meaning (red=bad, green=good) that shouldn't flip with light/dark mode. */
.sav-band-critically-weak { color: #c62828; font-weight: 700; }
.sav-band-below-average { color: #ef6c00; font-weight: 700; }
.sav-band-average { color: #f9a825; font-weight: 700; }
.sav-band-strong { color: #689f38; font-weight: 700; }
.sav-band-exceptional { color: #1b5e20; font-weight: 700; }

/* ---- Score meter: CSS-only horizontal bar, color-banded like the SAV
   legend above - reusable later for Shadbala/Vimshopaka/Bhava Bala. ---- */

.score-meter {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 160px;
}

.score-meter-track {
  flex: 1;
  height: 10px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.score-meter-fill {
  height: 100%;
  border-radius: 999px;
}

.score-meter-fill.sav-band-critically-weak { background: #e53935; }
.score-meter-fill.sav-band-below-average { background: #fb8c00; }
.score-meter-fill.sav-band-average { background: #fdd835; }
.score-meter-fill.sav-band-strong { background: #8bc34a; }
.score-meter-fill.sav-band-exceptional { background: #1b5e20; }

