/* ---- Bhava Ashtakavarga: CSS-only vertical bar chart, color-banded like
   the SAV legend above - one baseline, 12 columns, score labeled at the
   cap, house labeled on the axis below. ---- */

.bhava-bar-chart {
  display: flex;
  align-items: stretch;
  gap: 2px;
  margin: 1rem 0 1.25rem;
}

.bhava-bar-col {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.bhava-bar-value {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--text);
  font-variant-numeric: tabular-nums;
  margin-bottom: 0.3rem;
}

.bhava-bar-track {
  width: 100%;
  height: 160px;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  border-bottom: 1px solid var(--border);
}

.bhava-bar-fill {
  width: 100%;
  max-width: 22px;
  min-height: 2px;
  border-radius: 4px 4px 0 0;
}

.bhava-bar-fill.sav-band-critically-weak { background: #e53935; }
.bhava-bar-fill.sav-band-below-average { background: #fb8c00; }
