/* Bindu-count heatmap: 0-8 scale blended between the panel color and the
   primary accent, so higher scores read visually "hotter" at a glance -
   the "graph" feel, without any charting library or JS. */
.mini-chart-cell.bindus-0 { background: var(--panel); }
.mini-chart-cell.bindus-1 { background: color-mix(in srgb, var(--accent) 10%, var(--panel)); }
.mini-chart-cell.bindus-2 { background: color-mix(in srgb, var(--accent) 20%, var(--panel)); }
.mini-chart-cell.bindus-3 { background: color-mix(in srgb, var(--accent) 32%, var(--panel)); }
.mini-chart-cell.bindus-4 { background: color-mix(in srgb, var(--accent) 44%, var(--panel)); color: var(--text); }
.mini-chart-cell.bindus-5 { background: color-mix(in srgb, var(--accent) 56%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-6 { background: color-mix(in srgb, var(--accent) 68%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-7 { background: color-mix(in srgb, var(--accent) 82%, var(--panel)); color: #fff; }
.mini-chart-cell.bindus-8 { background: var(--accent); color: #fff; }

.mini-chart-cell.bindus-4 .cell-sign,
.mini-chart-cell.bindus-5 .cell-sign,
.mini-chart-cell.bindus-6 .cell-sign,
.mini-chart-cell.bindus-7 .cell-sign,
.mini-chart-cell.bindus-8 .cell-sign {
  color: inherit;
  opacity: 0.85;
}

.cell-bindus {
  font-weight: 700;
  font-size: 0.72rem;
}

